#!/usr/bin/env python3
"""Arrangement controls for Design 2.0 Inspector."""

def install(html):
    css=r'''<style id="d2-arrange-css">#d2-arrange{margin-top:12px}.d2-arrange-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.d2-arrange-grid button,.d2-group-actions button{margin:0!important;padding:6px 4px!important;font:10px Inter,sans-serif!important}.d2-group-actions{display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:5px}.d2-group-readout{margin:6px 0;color:#8b8579;font:9px ui-monospace,monospace}</style>'''
    panel=r'''<div id="d2-arrange"><div class="d2-section-title">ARRANGE</div><div id="d2-selection-readout" class="d2-group-readout">1 selected</div><div class="d2-arrange-grid"><button data-align="left">L</button><button data-align="center">C</button><button data-align="right">R</button><button data-align="top">T</button><button data-align="middle">M</button><button data-align="bottom">B</button></div><div class="d2-group-actions"><button id="d2-group">Group</button><button id="d2-ungroup">Ungroup</button></div></div>'''
    js=r'''<script id="d2-arrange-js">(()=>{const g=id=>document.getElementById(id);let ids=[];function currentIds(){return ids.length?ids:(selected?.id?[selected.id]:[])}function send(op,extra={}){const list=currentIds();if(!list.length)return;const frame=g('canvas');frame.contentWindow.postMessage({type:'d2-canvas-command',page_id:active,op,ids:list,...extra},'*')}document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>send('align_nodes',{mode:b.dataset.align}));g('d2-group').onclick=()=>send('group_nodes',{group_id:'group-'+Date.now().toString(36)});g('d2-ungroup').onclick=()=>send('ungroup_nodes');window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='dore-selection-set'&&m.page_id===active){ids=m.ids||[];g('d2-selection-readout').textContent=ids.length+' selected'}if(m.type==='dore-locked'&&m.page_id===active)g('status').textContent='LOCKED · '+m.id});const oldSelect=select;select=function(id,field,value,el){oldSelect(id,field,value,el);if(!ids.includes(id))ids=[id];g('d2-selection-readout').textContent=ids.length+' selected'}})()</script>'''
    return html.replace('</head>',css+'</head>',1).replace('<div id="d2-geometry" hidden>','<div id="d2-geometry" hidden>',1).replace('</div><p class="hint">Homepage and Journal are separate workspace pages.','</div>'+panel+'<p class="hint">Homepage and Journal are separate workspace pages.',1).replace('</body>',js+'</body>',1)
